card_mod.style:
ha-card {
  background: none;
  box-shadow: none;
  border: none;
  border-bottom: 1px solid rgba(127,127,127,0.18);
  padding: 0 0 6px 0;
  margin-bottom: 8px;
}

ha-card {
  background-color: var(--card-background-color, #1b1b1f);
  border: 1px solid rgba(127,127,127,0.30);
  border-left: 4px solid var(--accent-color, #03a9f4);
  border-radius: 12px;
  padding: 10px;
  margin-bottom: 10px;
} width: 100%;

